S = "Hakeem Force Academy"
QS = [
(S, "What is the meaning of the idiom 'to have an axe to grind'?", ["To be very angry with someone", "To have a private or selfish motive", "To work very hard", "To be good at cutting wood"], 1, "The idiom means having a personal or selfish reason for being involved in something or for giving an opinion.", "The phrase is often said to come from a story by Benjamin Franklin about a boy tricked into grinding an axe.", [3201]),
(S, "What is the meaning of the word 'pulchritudinous'?", ["Ugly", "Beautiful", "Clever", "Lazy"], 1, "Pulchritudinous is an adjective that means physically beautiful.", "The noun form is 'pulchritude', meaning beauty.", [3202]),
(S, "What is the meaning of the word 'arguable'?", ["Impossible to discuss", "Open to debate or able to be argued", "Very angry", "Completely proven"], 1, "Arguable describes something that can be reasonably argued or is open to debate.", "Its opposite in sense is 'indisputable'.", [3204]),
(S, "What is the meaning of the word 'bibliophile'?", ["A person who loves books", "A person who writes poems", "A person who sells paper", "A person who fears books"], 0, "The word comes from Greek 'biblion' (book) and 'philos' (loving), so a bibliophile is a lover of books.", "A person who collects rare books is also called a bibliophile.", [3205]),
(S, "What is the meaning of the word 'Hadith'?", ["A saying or tradition of the Holy Prophet (PBUH)", "A pilgrimage to Makkah", "A book of prayers", "A type of charity"], 0, "Hadith means a report, saying or tradition. In Islam it is the record of the sayings, actions and approvals of the Holy Prophet (PBUH).", "The Sunnah and Hadith are the second main source of Islamic law after the Quran.", [660]),
(S, "What is the meaning of the word 'obsolete'?", ["Very modern", "No longer used or out of date", "Extremely valuable", "Newly invented"], 1, "Obsolete means no longer in use because something newer has replaced it.", "Its antonym is 'current' or 'modern'.", [3211]),
(S, "What is the meaning of the word 'privilege'?", ["A heavy duty", "A punishment", "A special right or advantage", "A common habit"], 2, "A privilege is a special right or benefit given to a person or group.", "A privilege is usually not available to everyone.", [3213]),
(S, "G20 leaders summit of 2023 was held in which country?", ["Indonesia", "Brazil", "India", "Japan"], 2, "The 2023 G20 summit was held in New Delhi, India, in September 2023.", "The 2022 summit was in Indonesia (Bali) and the 2024 summit was in Brazil (Rio de Janeiro).", [241, 1233]),
(S, "The ancient Mehrgarh civilization site, one of the oldest farming settlements in South Asia, is located in which province of Pakistan?", ["Sindh", "Balochistan", "Punjab", "Khyber Pakhtunkhwa"], 1, "Mehrgarh lies on the Kachhi plain near the Bolan Pass in Balochistan.", "Mehrgarh dates back to about 7000 BC and came before the Indus Valley civilization.", [254, 3696]),
(S, "Pakistan is a member of which of these organisations?", ["NATO", "Organisation of Islamic Cooperation (OIC)", "European Union", "ASEAN"], 1, "Pakistan is a member of the OIC. It is not a member of NATO, the EU or ASEAN.", "Pakistan has been a member of the OIC since its founding in 1969.", [2381]),
(S, "How many member countries does SAARC have?", ["7", "9", "8", "6"], 2, "SAARC has eight members: Pakistan, India, Bangladesh, Sri Lanka, Nepal, Bhutan, Maldives and Afghanistan.", "Afghanistan joined as the eighth member in 2007.", [1845]),
(S, "The former princely state of Swat merged into Pakistan's which province?", ["Punjab", "Sindh", "Balochistan", "Khyber Pakhtunkhwa (then NWFP)"], 3, "Swat became part of the North-West Frontier Province, now Khyber Pakhtunkhwa, after it merged fully in 1969.", "Swat had earlier acceded to Pakistan in 1947 but kept its own ruler until 1969.", [2595]),
(S, "Adnan walks 10 meters towards the north, then walks towards the south. After this he turns back and then turns left. In which direction is he facing now?", ["East", "South", "North", "West"], 3, "After walking south he faces south. Turning back makes him face north. Turning left from north makes him face west.", "Left of north is west and right of north is east.", [1515]),
(S, "How many peaks above 8000 metres are there in Pakistan?", ["4", "5", "6", "3"], 1, "The five are K2, Nanga Parbat, Gasherbrum I, Broad Peak and Gasherbrum II.", "Pakistan has five of the world's fourteen 8000 metre peaks.", [1854, 553]),
(S, "Fill in the blank: I bought milk ___ 12 rupees.", ["with", "at", "by", "for"], 3, "The preposition 'for' is used to show the price paid for something.", "'At' is used for a rate, such as 'at 12 rupees per litre'.", [1708, 887]),
(S, "A man covers 20 km in 1 hour and 40 minutes. How many km does he cover in one minute?", ["0.2 km", "0.5 km", "2 km", "0.02 km"], 0, "1 hour 40 minutes = 100 minutes. Distance per minute = 20 / 100 = 0.2 km.", "0.2 km equals 200 metres per minute, or 12 km per hour.", [1455]),
(S, "If 5 people do 5 tasks in 5 minutes, how many tasks will 1 person do in 1 minute?", ["5 tasks", "1 task", "0.5 task", "0.2 task"], 3, "5 people do 5 tasks in 5 minutes, so 1 person does 1 task in 5 minutes. In 1 minute he does 1/5 = 0.2 task.", "The rate of work for each person is 1 task per 5 minutes.", [1930]),
]
